SELECT q.*,d.name applicant_dept_name,au.username applicant_username,au.real_name applicant_real_name, du.username dept_username,du.real_name dept_real_name,su.username science_username,su.real_name science_real_name, (SELECT GROUP_CONCAT(r.code ORDER BY r.code SEPARATOR ',') FROM user_role ur JOIN app_role r ON r.id=ur.role_id WHERE ur.user_id=q.user_id) applicant_roles, (SELECT GROUP_CONCAT(r.code ORDER BY r.code SEPARATOR ',') FROM user_role ur JOIN app_role r ON r.id=ur.role_id WHERE ur.user_id=q.dept_reviewer_user_id) dept_roles, (SELECT GROUP_CONCAT(r.code ORDER BY r.code SEPARATOR ',') FROM user_role ur JOIN app_role r ON r.id=ur.role_id WHERE ur.user_id=q.science_reviewer_user_id) science_roles FROM expert_qualification q LEFT JOIN department d ON d.id=q.applicant_dept_id JOIN app_user au ON au.id=q.user_id LEFT JOIN app_user du ON du.id=q.dept_reviewer_user_id LEFT JOIN app_user su ON su.id=q.science_reviewer_user_id
q.id=#{filter.id} AND q.user_id=#{filter.userId} AND q.applicant_dept_id=#{filter.departmentId,jdbcType=BIGINT}
ORDER BY q.id DESC
